[
    {
        "name": "decidir_aprovacao_gestor",
        "definition": "CREATE OR REPLACE FUNCTION public.decidir_aprovacao_gestor(p_colaborador_id uuid, p_ciclo_id uuid, p_decisao text, p_justificativa text DEFAULT NULL::text, p_idempotencia text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid       uuid := auth.uid();
  v_email     text := nullif(current_setting('request.jwt.claims', true)::jsonb ->> 'email', '');
  v_decisao   text := lower(btrim(coalesce(p_decisao, '')));
  v_just      text := nullif(btrim(coalesce(p_justificativa, '')), '');
  v_chave     text;
  v_hash      text;
  v_confere   text;
  v_anterior  jsonb;
  v_linha     public.feedbacks_360%rowtype;
  v_cons      public.feedbacks_360_consolidacoes%rowtype;
  v_versao    text;
  v_versao_atual text;
  v_status    text;
  v_id        uuid;
  v_resultado jsonb;
  v_desempenho numeric;
  v_potencial  numeric;
  v_soma_pesos numeric := 0;
  v_soma_notas numeric := 0;
  v_peso       numeric;
  v_tem_gestor boolean := false;
  v_snapshot   jsonb;
  v_cat        record;
begin
  if v_uid is null then
    raise exception 'nao_autenticado' using errcode = '28000';
  end if;
  if p_idempotencia is null or btrim(p_idempotencia) = '' then
    raise exception 'idempotencia_ausente';
  end if;
  if v_decisao not in ('aprovado','devolvido') then
    raise exception 'decisao_invalida';
  end if;
  if v_decisao = 'devolvido' and (v_just is null or length(v_just) < 10) then
    raise exception 'justificativa_obrigatoria';
  end if;

  -- PERMISSÃO: gestor vinculado ou exceção autenticada de homologação. Autoria do feedback permitida; autorização do gestor obrigatória.
  if not public.pode_aprovar_colaborador(p_colaborador_id) then
    raise exception 'perfil_nao_autorizado';
  end if;

  -- A consolidação é a chave ÚNICA (empresa + ciclo + colaborador) e o LOCK
  -- serializa duas aprovações concorrentes do mesmo conjunto.
  select * into v_cons
    from public.feedbacks_360_consolidacoes c
   where c.colaborador_id = p_colaborador_id
     and c.ciclo_id = p_ciclo_id
   for update;
  if not found then
    perform public.sincronizar_consolidacao_avaliacao(p_colaborador_id, p_ciclo_id, v_uid);
    select * into v_cons
      from public.feedbacks_360_consolidacoes c
     where c.colaborador_id = p_colaborador_id
       and c.ciclo_id = p_ciclo_id
     for update;
  end if;
  if not found then
    raise exception 'consolidacao_ausente';
  end if;
  if v_cons.empresa_id is null
     or v_cons.empresa_id not in (select public.get_user_empresas(v_uid)) then
    raise exception 'nao_autorizado';
  end if;
  if not exists (select 1 from public.colaboradores c
                  where c.id=p_colaborador_id and c.empresa_id=v_cons.empresa_id)
     or not exists (select 1 from public.ciclos_avaliacao ca
                     where ca.id=p_ciclo_id and ca.empresa_id=v_cons.empresa_id) then
    raise exception 'empresa_ciclo_colaborador_inconsistentes';
  end if;

  v_versao := coalesce(v_cons.versao_consolidada,
                       public.versao_consolidada_avaliacao(p_colaborador_id, p_ciclo_id));
  v_versao_atual := public.versao_consolidada_avaliacao(p_colaborador_id, p_ciclo_id);
  if v_versao is null then
    raise exception 'sem_avaliacao';
  end if;
  if v_versao_atual is distinct from v_versao then
    raise exception 'versao_desatualizada';
  end if;
  -- Verificar novamente a versão depois de bloquear as avaliações existentes.
  perform 1 from public.feedbacks_360 f
   where f.avaliado_id = p_colaborador_id and f.ciclo_id = p_ciclo_id
   for update;
  if public.versao_consolidada_avaliacao(p_colaborador_id,p_ciclo_id)
       is distinct from v_versao then
    raise exception 'versao_desatualizada';
  end if;

  /**
   * REGISTRO DE REFERÊNCIA: prioriza `tipo='gestor'`, mas NÃO o exige. O RH
   * pode preparar o conjunto em qualquer categoria; o gestor aprova a proposta
   * consolidada. O registro precisa estar concluído e não cancelado.
   */
  select * into v_linha
    from public.feedbacks_360 f
   where f.avaliado_id = p_colaborador_id
     and f.ciclo_id = p_ciclo_id
     and lower(btrim(coalesce(f.status, ''))) = 'concluido'
     and lower(btrim(coalesce(f.tipo, ''))) in ('gestor','par','auto','subordinado')
   order by (lower(btrim(coalesce(f.tipo, ''))) = 'gestor') desc,
            f.updated_at desc nulls last
   limit 1;
  if not found then
    raise exception 'avaliacao_consolidada_ausente';
  end if;

  -- Gestor autorizado pode criar e aprovar o feedback; autoria nao bloqueia decisao.

  v_chave := 'decidir_aprovacao:' || p_colaborador_id::text || ':' || p_ciclo_id::text || ':' || p_idempotencia;
  v_hash  := md5(p_colaborador_id::text || '|' || p_ciclo_id::text || '|' || v_decisao || '|' || coalesce(v_just, ''));

  select resultado, hash_parametros into v_anterior, v_confere
    from public.feedbacks_360_operacoes
   where idempotency_key = v_chave and empresa_id = v_cons.empresa_id;
  if found then
    if v_confere <> v_hash then
      raise exception 'idempotencia_conflito';
    end if;
    return v_anterior || jsonb_build_object('idempotente', true);
  end if;

  if public.situacao_aprovacao(p_colaborador_id, p_ciclo_id) not in ('aguardando_gestor', 'sem_gestor') then
    raise exception 'pendencia_nao_aguarda_decisao';
  end if;


  if v_decisao = 'aprovado' then
    /*
     * DESEMPENHO: mesma composição 360 do motor do front - última avaliação
     * elegível por categoria, pesos 60/25/10/5, renormalizados sobre as
     * categorias disponíveis. Se NÃO existe categoria Gestor, usa-se a
     * proposta consolidada do RH (nota + potencial do registro de referência).
     */
    for v_cat in
      select distinct on (lower(btrim(coalesce(f.tipo, ''))))
             lower(btrim(coalesce(f.tipo, ''))) as tipo,
             f.nota_geral,
             f.potencial
        from public.feedbacks_360 f
       where f.avaliado_id = p_colaborador_id
         and f.ciclo_id = p_ciclo_id
         and lower(btrim(coalesce(f.status, ''))) = 'concluido'
         and lower(btrim(coalesce(f.tipo, ''))) in ('gestor','par','auto','subordinado')
         and f.nota_geral between 1 and 5
       order by lower(btrim(coalesce(f.tipo, ''))), f.updated_at desc nulls last
    loop
      v_peso := case v_cat.tipo
                  when 'gestor' then 0.60
                  when 'par' then 0.25
                  when 'auto' then 0.10
                  when 'subordinado' then 0.05
                  else 0
                end;
      v_soma_pesos := v_soma_pesos + v_peso;
      v_soma_notas := v_soma_notas + (v_cat.nota_geral * v_peso);
      if v_cat.tipo = 'gestor' then
        v_tem_gestor := true;
        v_potencial := v_cat.potencial;
      end if;
    end loop;

    if v_tem_gestor then
      if v_potencial is null or v_potencial < 1 or v_potencial > 5 then
        raise exception 'avaliacao_sem_potencial';
      end if;
      if v_soma_pesos <= 0 then
        raise exception 'avaliacao_sem_desempenho';
      end if;
      v_desempenho := v_soma_notas / v_soma_pesos;
    else
      -- Proposta consolidada do RH: precisa dos DOIS valores no registro.
      if v_linha.nota_geral is null or v_linha.nota_geral < 1 or v_linha.nota_geral > 5 then
        raise exception 'avaliacao_sem_desempenho';
      end if;
      if v_linha.potencial is null or v_linha.potencial < 1 or v_linha.potencial > 5 then
        raise exception 'avaliacao_sem_potencial';
      end if;
      v_desempenho := v_linha.nota_geral;
      v_potencial := v_linha.potencial;
    end if;

    if v_desempenho is null or v_desempenho < 1 or v_desempenho > 5 then
      raise exception 'avaliacao_sem_desempenho';
    end if;

    v_snapshot := jsonb_build_object(
      'desempenho', v_desempenho,
      'potencial', v_potencial,
      'versao_consolidada', v_versao,
      'regra', case when v_tem_gestor then '360_gestor' else 'proposta_consolidada_rh' end,
      'fonte_feedback_id', v_linha.id,
      'fonte_tipo', lower(btrim(coalesce(v_linha.tipo, ''))),
      'aprovado_em', now()
    );
    v_status := 'aprovada_gestor';
  else
    v_status := 'devolvida';
    v_desempenho := null;
    v_potencial := null;
    v_snapshot := null;
  end if;

  insert into public.feedbacks_360_aprovacoes_gestor (
    consolidacao_id, feedback_id, empresa_id, ciclo_id, colaborador_id,
    decisao, justificativa, versao_avaliacao, revisao,
    decidido_por, idempotency_key, hash_parametros
  ) values (
    v_cons.id, v_linha.id, v_cons.empresa_id, p_ciclo_id, p_colaborador_id,
    v_decisao, v_just, v_versao, v_cons.revisao,
    v_uid, 'aprov:' || v_chave, v_hash
  ) returning id into v_id;

  update public.feedbacks_360_consolidacoes
     set status = v_status,
         desempenho_aprovado = v_desempenho,
         potencial_aprovado = v_potencial,
         aprovado_por = case when v_decisao = 'aprovado' then v_uid else null end,
         aprovado_em = case when v_decisao = 'aprovado' then now() else null end,
         aprovacao_id = case when v_decisao = 'aprovado' then v_id else null end,
         snapshot_aprovado = v_snapshot,
         atualizado_em = now()
   where id = v_cons.id;

  insert into public.audit_log (
    empresa_id, tabela, registro_id, acao, dados_anteriores, dados_novos, campos_alterados, user_id, user_email
  ) values (
    v_cons.empresa_id,
    'feedbacks_360_aprovacoes_gestor', v_id, 'INSERT', null,
    jsonb_build_object(
      'empresa_id', v_cons.empresa_id,
      'ciclo_id', p_ciclo_id,
      'colaborador_id', p_colaborador_id,
      'decisao', v_decisao,
      'versao_avaliacao', v_versao,
      'revisao_avaliada', v_cons.revisao,
      'desempenho_aprovado', v_desempenho,
      'potencial_aprovado', v_potencial,
      'snapshot_aprovado', v_snapshot
    ),
    array['decisao', 'versao_avaliacao', 'desempenho_aprovado', 'potencial_aprovado'],
    v_uid, v_email
  );

  v_resultado := jsonb_build_object(
    'ok', true,
    'aprovacao_id', v_id,
    'decisao', v_decisao,
    'status', v_status,
    'versao_avaliacao', v_versao,
    'desempenho_aprovado', v_desempenho,
    'potencial_aprovado', v_potencial,
    'snapshot_aprovado', v_snapshot,
    'idempotente', false
  );

  insert into public.feedbacks_360_operacoes
    (idempotency_key, feedback_id, empresa_id, operacao, hash_parametros, resultado)
  values (v_chave, v_linha.id, v_cons.empresa_id, 'decidir_aprovacao_gestor', v_hash, v_resultado)
  on conflict (idempotency_key) do nothing;

  return v_resultado;
end;
$function$
"
    },
    {
        "name": "finalizar_feedback",
        "definition": "CREATE OR REPLACE FUNCTION public.finalizar_feedback(p_feedback_id uuid, p_acao text, p_motivo text DEFAULT NULL::text, p_idempotencia text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid          uuid := auth.uid();
  v_email        text := nullif(current_setting('request.jwt.claims', true)::jsonb ->> 'email', '');
  v_hash         text;
  v_chave        text;
  v_linha        public.feedbacks_360%rowtype;
  v_novo         text;
  v_auditoria_id uuid;
  v_resultado    jsonb;
  v_confere      text;
  v_anterior     jsonb;
  v_nota         numeric;
  v_revisao      integer;
begin
  if v_uid is null then
    raise exception 'nao_autenticado' using errcode = '28000';
  end if;
  if p_acao not in ('concluir','cancelar','reabrir') then
    raise exception 'acao_invalida';
  end if;
  if p_idempotencia is null or btrim(p_idempotencia) = '' then
    raise exception 'idempotencia_ausente';
  end if;

  -- ── AUTORIZAÇÃO PRIMEIRO; IDEMPOTÊNCIA DEPOIS ──────────────────────────────
  -- O REENVIO É UM CAMINHO DE LEITURA: ele devolve `status_anterior`,
  -- `auditoria_id` e o resultado gravado daquela operação. Responder ao reenvio
  -- antes de checar papel e empresa transformava a idempotência numa PORTA
  -- LATERAL - a função é `SECURITY DEFINER`, então quem apresentasse a chave
  -- receberia o resultado de OUTRO tenant sem passar por policy nenhuma.
  -- Ordem obrigatória (e é a mesma nas três RPCs):
  --   1. autenticação .................................... (acima)
  --   2. PAPEL REAL do banco (`pode_gerir_avaliacoes()`);
  --   3. linha carregada COM TRAVA (`for update`) - serializa concorrentes;
  --   4. EMPRESA (tenant) da própria linha;
  --   5. SÓ ENTÃO a chave de idempotência.
  -- Papel REAL do banco (helper único, ver §0c): concluir/cancelar/reabrir são de
  -- `admin` (proprietário) e `rh`. `gestor` e `user` NÃO têm acesso.
  if not public.pode_gerir_avaliacoes() then
    raise exception 'perfil_nao_autorizado';
  end if;

  v_chave := p_acao || ':' || p_feedback_id::text || ':' || p_idempotencia;
  v_hash  := md5(p_feedback_id::text || '|' || p_acao || '|' || coalesce(p_motivo, ''));

  -- Concorrência: trava a linha antes de decidir.
  select * into v_linha from public.feedbacks_360 where id = p_feedback_id for update;
  if not found then
    raise exception 'registro_inexistente';
  end if;

  -- Tenant DENTRO da função (SECURITY DEFINER não passa por RLS).
  if v_linha.empresa_id is null
     or v_linha.empresa_id not in (select public.get_user_empresas(v_uid)) then
    raise exception 'nao_autorizado';
  end if;

  -- Idempotência: mesma chave + mesmos parâmetros devolve o resultado anterior.
  -- `empresa_id` e `feedback_id` repetidos aqui de propósito: mesmo que a chave
  -- fosse adivinhada/forjada, ela só casa com a operação da PRÓPRIA empresa e do
  -- PRÓPRIO feedback já autorizados acima (defesa em profundidade).
  select resultado, hash_parametros into v_anterior, v_confere
    from public.feedbacks_360_operacoes
   where idempotency_key = v_chave
     and empresa_id = v_linha.empresa_id
     and feedback_id = p_feedback_id;
  if found then
    if v_confere <> v_hash then
      raise exception 'idempotencia_conflito';
    end if;
    return v_anterior || jsonb_build_object('idempotente', true);
  end if;

  -- Máquina de estados (§9): concluidocancelado exige reabrir antes.
  v_novo := case
    when coalesce(lower(btrim(v_linha.status)), '') = 'pendente' and p_acao = 'concluir' then 'concluido'
    when coalesce(lower(btrim(v_linha.status)), '') = 'pendente' and p_acao = 'cancelar' then 'cancelado'
    when coalesce(lower(btrim(v_linha.status)), '') in ('concluido','cancelado')
         and p_acao = 'reabrir' then 'pendente'
    else null
  end;
  if v_novo is null then
    raise exception 'transicao_invalida';
  end if;

  -- Reabrir é recurso de RH/proprietário (e exige justificativa, §9.3).
  if p_acao = 'reabrir' and (p_motivo is null or length(btrim(p_motivo)) < 10) then
    raise exception 'justificativa_obrigatoria';
  end if;
  if p_acao = 'cancelar' and (p_motivo is null or length(btrim(p_motivo)) < 3) then
    raise exception 'motivo_obrigatorio';
  end if;
  -- ── CONCLUIR: TODAS as condições obrigatórias, POR CATEGORIA (§6.1) ────────
  -- O servidor é o guardião: o front NÃO bloqueia "Concluir" por falta de nota
  -- (ele só não oferece controle que o status/papel recusa - ver
  -- `FeedbackAcoesRodape`), então estas checagens são a única barreira real.
  if p_acao = 'concluir' then
    -- (a) A CATEGORIA precisa ser uma das quatro do 360°. Sem isso não existe
    --     regra aprovada de elegibilidade, e a avaliação nunca classificaria.
    if coalesce(lower(btrim(v_linha.tipo)), '') not in ('gestor','par','auto','subordinado') then
      raise exception 'categoria_invalida';
    end if;

    -- (b) IDENTIFICAÇÃO E RASTREABILIDADE DA ORIGEM - espelho de
    --     `statusFeedback.validarConclusao` (os mesmos impedimentos
    --     `avaliado_ausente`, `avaliador_ausente` e `ciclo_ausente`). O contrato
    --     do formulário já exige avaliado E avaliador (`podeSalvar =
    --     Boolean(avaliadoId && avaliadorId)`) e a avaliação só existe dentro de
    --     um ciclo: sem esses três vínculos não há a quem atribuir a avaliação
    --     nem de onde rastrear sua origem. A checagem vale tanto para os
    --     registros da criação segura quanto para os do INSERT direto
    --     temporário - o registro pode ter nascido com a coluna nula, e é AQUI
    --     que a conclusão inverte para recusa. Não exige mais que isso: a
    --     existência dos vínculos é garantida pelas FKs.
    if v_linha.avaliado_id is null then
      raise exception 'avaliado_ausente';
    end if;
    if v_linha.avaliador_id is null then
      raise exception 'avaliador_ausente';
    end if;
    if v_linha.ciclo_id is null then
      raise exception 'ciclo_ausente';
    end if;

    -- (c) TODAS as categorias: nota de desempenho NA ESCALA 1-5. "Preenchida"
    --     não basta: `performance` é `INTEGER CHECK (1..5)`, mas **`nota_geral`
    --     é `NUMERIC` SEM CHECK** e a regra usa `coalesce(performance,
    --     nota_geral)` - sem o teste de faixa, concluía com 0, 7 ou -3.
    v_nota := coalesce(v_linha.performance, v_linha.nota_geral);
    if v_nota is null then
      raise exception 'dados_incompletos';
    end if;
    if v_nota < 1 or v_nota > 5 then
      raise exception 'nota_desempenho_fora_da_escala';
    end if;

    -- (d) Potencial, QUANDO informado, tem de estar na escala 1-5 - para
    --     QUALQUER categoria. O `CHECK (1..5)` da coluna já barra no INSERT, mas
    --     o servidor confere aqui também (defesa em profundidade: a coluna é
    --     `integer` e pode ter sido tocada por via privilegiada). Não altera a
    --     regra de obrigatoriedade - só garante a escala.
    if v_linha.potencial is not null and (v_linha.potencial < 1 or v_linha.potencial > 5) then
      raise exception 'potencial_fora_da_escala';
    end if;

    -- (e) OBRIGATÓRIO apenas para o GESTOR: o Potencial é campo da avaliação do
    --     gestor - é 100% do eixo horizontal do Nine-Box (`gestor_sem_potencial`
    --     no motor). Pares/Auto/Subordinados **NÃO** fornecem Potencial (§6.1) e
    --     continuam concluindo sem ele: exigi-lo seria bloquear avaliação
    --     legítima. A régua do servidor é a mesma que o front aplica - e o front
    --     não é a barreira.
    if lower(btrim(v_linha.tipo)) = 'gestor' and v_linha.potencial is null then
      raise exception 'potencial_obrigatorio_para_gestor';
    end if;
  end if;

  -- A REVISÃO (§0.1) é incrementada pelo TRIGGER `trg_feedbacks_360_revisao` a
  -- cada UPDATE - inclusive neste. A RPC NÃO a incrementa à mão (seria contagem
  -- DOBRADA). O `returning` devolve o número NOVO já gravado pelo trigger, para
  -- o resultado e para a trilha.
  update public.feedbacks_360
     set status = v_novo,
         updated_at = now()
   where id = p_feedback_id
  returning revisao into v_revisao;

  -- AUDITORIA VINCULADA À EMPRESA (§0g). A `audit_log` canônica TEM a coluna
  -- `empresa_id` - é ela que a policy `audit_log_tenant_select` e a RPC
  -- `listar_auditoria` usam para recortar a Trilha por tenant. O vínculo vai,
  -- portanto, na COLUNA **e** é replicado em `dados_novos.empresa_id` (defesa
  -- em profundidade e leitura direta pela timeline) junto do `status` e da
  -- `revisao` resultantes. Sem a coluna preenchida o evento existiria, mas
  -- ficaria INVISÍVEL para a própria empresa.
  insert into public.audit_log (
    empresa_id, tabela, registro_id, acao, dados_anteriores, dados_novos, campos_alterados, user_id, user_email
  ) values (
    v_linha.empresa_id,
    'feedbacks_360', p_feedback_id, 'UPDATE',
    jsonb_build_object('status', v_linha.status, 'revisao', v_linha.revisao),
    jsonb_build_object(
      'empresa_id', v_linha.empresa_id,
      'status', v_novo,
      'revisao', v_revisao
    ),
    array['status'], v_uid, v_email
  ) returning id into v_auditoria_id;

  v_resultado := jsonb_build_object(
    'ok', true,
    'status_anterior', v_linha.status,
    'status_novo', v_novo,
    'revisao_nova', v_revisao,
    'auditoria_id', v_auditoria_id,
    'idempotente', false
  );

  insert into public.feedbacks_360_operacoes
    (idempotency_key, feedback_id, empresa_id, operacao, hash_parametros, resultado)
  values (v_chave, p_feedback_id, v_linha.empresa_id, p_acao, v_hash, v_resultado)
  on conflict (idempotency_key) do nothing;

  return v_resultado;
end;
$function$
"
    },
    {
        "name": "pode_aprovar_colaborador",
        "definition": "CREATE OR REPLACE FUNCTION public.pode_aprovar_colaborador(p_colaborador_id uuid)
 RETURNS boolean
 LANGUAGE sql
